    n_edges = 26

    # Edge list: (u, v) pairs
    edges = []
    for g in range(3):
        for i in range(4):
            for j in range(i+1, 4):
                edges.append((g*4+i, g*4+j))
    for g in range(2):
        for i in range(4):
            edges.append((g*4+i, (g+1)*4+i))

    # Build adjacency info
    vertex_edges = [[] for _ in range(n_vertices)]
    for idx, (u, v) in enumerate(edges):
        vertex_edges[u].append(idx)
        vertex_edges[v].append(idx)

    # Backtracking with proper tracking
    labels = [-1] * n_vertices
    used_labels = set()
    edge_diffs = [-1] * n_edges  # diff for each edge

    def backtrack(vertex_idx):
        if vertex_idx == n_vertices:
            return True

        # Try each possible label
        for label in range(n_edges + 1):  # 0 to 26
            if label in used_labels:
                continue

            # Check if this label creates any duplicate edge differences
            labels[vertex_idx] = label
            new_diffs = []
            valid = True

            for edge_idx in vertex_edges[vertex_idx]:
                u, w = edges[edge_idx]
                other = w if u == vertex_idx else u
                if labels[other] >= 0:
                    d = abs(label - labels[other])
                    if d == 0 or d > n_edges or edge_diffs[edge_idx] >= 0:
                        valid = False
                        break
                    # Check if this diff is already used by another edge
                    conflict = False
                    for other_edge_idx in range(n_edges):
                        if other_edge_idx != edge_idx and edge_diffs[other_edge_idx] == d:
                            conflict = True
                            break
                    if conflict:
                        valid = False
                        break
                    new_diffs.append((edge_idx, d))

            if valid:
                used_labels.add(label)
                for edge_idx, d in new_diffs:
                    edge_diffs[edge_idx] = d

                if backtrack(vertex_idx + 1):
                    return True

                used_labels.remove(label)
                for edge_idx, d in new_diffs:
                    edge_diffs[edge_idx] = -1

            labels[vertex_idx] = -1

        return False

    if backtrack(0):
        return labels
    return None

